prompt APPLICATION 100 - Hader
--
-- Application Export:
--   Application:     100
--   Name:            Hader
--   Exported By:     HADER
--   Flashback:       0
--   Export Type:     Component Export
--   Manifest
--     PLUGIN: COM.HADER.AI_SERVICES
--   Manifest End
--   Version:         19.2.0.00.18
--   Instance ID:     1
--

prompt --application/shared_components/plugins/region_type/com_hader_ai_services
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(91735000000001)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.HADER.AI_SERVICES'
,p_display_name=>'Hader AI Services (حاضر - خدمات الذكاء الاصطناعي)'
,p_supported_ui_types=>'DESKTOP:JQM_SMARTPHONE'
,p_javascript_file_urls=>'#PLUGIN_FILES#hader-ai.js
#PLUGIN_FILES#hader-ai-services.js'
,p_css_file_urls=>'#PLUGIN_FILES#hader-ai-services.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Hader AI (APEX 19.2 and later): what every Hader AI plug-in answers (hader-ai.js). Everything goes through',
'-- HDR_AI, which checks the signed-in user (ai.use with Hader''s accounts; the page''s authorization without them).',
'--   SERVICE  the region''s service: where and how it is called (its key only when the browser calls it)',
'--   RELAY    a request of the region''s service when it is called from the database (p_clob_01 the body): rebuilt',
'--            and answered by HDR_AI, never another service than the region''s',
'--   TOOL     a question about the data (x02 its name, x03..x07 its values), of the groups the region allows',
'',
'function hdr_ai_obj (p_owner in varchar2, p_name in varchar2) return varchar2 is',
'begin',
'  if trim(p_owner) is null then',
'    return p_name;',
'  end if;',
'  if not regexp_like(trim(p_owner), ''^[A-Za-z][A-Za-z0-9_$#]{0,29}$'') then',
'    raise_application_error(-20001, ''Hader AI: invalid owner '' || p_owner);',
'  end if;',
'  return trim(p_owner) || ''.'' || p_name;',
'end hdr_ai_obj;',
'',
'-- the answer, as JSON (it never is a page)',
'procedure hdr_ai_print (p_clob in clob) is',
'  l_len number := nvl(dbms_lob.getlength(p_clob), 0);',
'begin',
'  sys.owa_util.mime_header(''application/json'', false, ''utf-8'');',
'  sys.owa_util.http_header_close;',
'  for i in 0 .. trunc((l_len - 1) / 8000) loop',
'    sys.htp.prn(dbms_lob.substr(p_clob, 8000, i * 8000 + 1));',
'  end loop;',
'end hdr_ai_print;',
'',
'-- Hader AI''s own messages as they are; anything else (the database''s, APEX''s) to a developer only',
'function hdr_ai_message (p_err in varchar2) return varchar2 is',
'  l_first varchar2(4000) := regexp_substr(p_err, ''^[^'' || chr(10) || '']*'');',
'begin',
'  if regexp_like(l_first, ''^ORA-(2067[0-9]|20699): '') then',
'    return regexp_replace(l_first, ''^ORA-[0-9]+: '');',
'  end if;',
'  return case when apex_application.g_debug or v(''APP_BUILDER_SESSION'') is not null then l_first',
'              when regexp_like(p_err, ''ORA-(06550|00942|04043)|PLS-00201'') then ''Hader AI is not installed in this schema (hader_ai_install.sql)''',
'              else ''The request failed (run the page with debug for the detail)'' end;',
'end hdr_ai_message;',
'',
'-- true when the call was one of these',
'function hdr_ai_common (p_owner in varchar2, p_service in varchar2, p_tools in varchar2) return boolean is',
'  l_clob   clob;',
'  l_name   varchar2(30) := lower(apex_application.g_x02);',
'  l_group  varchar2(30);',
'begin',
'  if apex_application.g_x01 = ''SERVICE'' then',
'    execute immediate ''begin :r := '' || hdr_ai_obj(p_owner, ''HDR_AI'') || ''.service(:u, :s); end;''',
'      using out l_clob, in v(''APP_USER''), in p_service;',
'    hdr_ai_print(l_clob);',
'  elsif apex_application.g_x01 = ''RELAY'' then',
'    -- the region''s own service, whatever the page says',
'    execute immediate ''begin :r := '' || hdr_ai_obj(p_owner, ''HDR_AI'') || ''.relay(:u, :s, :b); end;''',
'      using out l_clob, in v(''APP_USER''), in p_service, in apex_application.g_clob_01;',
'    hdr_ai_print(l_clob);',
'  elsif apex_application.g_x01 = ''TOOL'' then',
'    l_group := case when l_name = ''terminals'' then ''TERMINALS'' else ''ATTENDANCE'' end;',
'    if instr('':'' || upper(p_tools) || '':'', '':'' || l_group || '':'') = 0 then',
'      raise_application_error(-20671, ''not allowed in this region: '' || lower(l_group));',
'    end if;',
'    execute immediate ''begin :r := '' || hdr_ai_obj(p_owner, ''HDR_AI'') || ''.tool(:u, :n, :a1, :a2, :a3, :a4, :a5); end;''',
'      using out l_clob, in v(''APP_USER''), in l_name, in apex_application.g_x03, in apex_application.g_x04,',
'            in apex_application.g_x05, in apex_application.g_x06, in apex_application.g_x07;',
'    hdr_ai_print(l_clob);',
'  else',
'    return false;',
'  end if;',
'  return true;',
'end hdr_ai_common;',
'',
'procedure hdr_ai_failed (p_err in varchar2) is',
'begin',
'  apex_json.free_output;',
'  sys.htp.init;',
'  apex_json.open_object;                                -- with its own header: application/json',
'  apex_json.write(''failure'', hdr_ai_message(p_err));   -- not ''error'': apex.server takes that one for its own',
'  apex_json.close_object;',
'end hdr_ai_failed;',
'',
'-- Hader AI Services (region plug-in). APEX 19.2 and later, Oracle 11g and later.',
'-- The AI services of the workspace''s schema, as APEX 24 and later has them (Workspace Utilities > Generative AI):',
'-- provider, name, address and model, the key (written, never shown again) or a Web Credential, where the calls are',
'-- made from, and a test. The regions and actions of Hader AI use them by their static id.',
'-- (the functions every Hader AI plug-in shares come first: ai_core/ai_common.plsql)',
'',
'function hdr_ai_mode (p_region in apex_plugin.t_region) return varchar2 is',
'  l_mode varchar2(10);',
'begin',
'  execute immediate ''begin :m := '' || hdr_ai_obj(p_region.attribute_01, ''HDR_AI'') || ''.mode_; end;'' using out l_mode;',
'  return l_mode;',
'exception when others then',
'  return ''HADER'';                   -- in doubt, HDR_AI decides (system.admin)',
'end hdr_ai_mode;',
'',
'-- may this user see them, and test them: with Hader''s accounts HDR_AI decides (system.admin); without them (Hader AI',
'-- alone) the region''s authorization scheme, required',
'function can_see (p_region in apex_plugin.t_region) return boolean is',
'begin',
'  if hdr_ai_mode(p_region) = ''HADER'' then',
'    return p_region.attribute_03 is null or apex_authorization.is_authorized(p_region.attribute_03);',
'  end if;',
'  return p_region.attribute_03 is not null and apex_authorization.is_authorized(p_region.attribute_03);',
'exception when others then',
'  return false;',
'end can_see;',
'',
'-- and change them: the same, and the attribute',
'function can_change (p_region in apex_plugin.t_region) return boolean is',
'begin',
'  return nvl(p_region.attribute_02, ''Y'') = ''Y'' and can_see(p_region);',
'end can_change;',
'',
'function render (',
'  p_region              in apex_plugin.t_region,',
'  p_plugin              in apex_plugin.t_plugin,',
'  p_is_printer_friendly in boolean )',
'  return apex_plugin.t_region_render_result',
'is',
'  l_id   varchar2(255) := nvl(p_region.static_id, ''R'' || p_region.id) || ''_hais'';',
'  l_lang varchar2(2) := case nvl(p_region.attribute_04, ''AUTO'') when ''AR'' then ''ar'' when ''EN'' then ''en''',
'                             else case when lower(apex_util.get_session_lang) like ''ar%'' then ''ar'' else ''en'' end end;',
'begin',
'  if not can_see(p_region) then',
'    sys.htp.p(''<div class="hais"><p class="hais-fail" dir="'' || case when l_lang = ''ar'' then ''rtl'' else ''ltr'' end || ''">''',
'      || case when p_region.attribute_03 is not null                   -- a scheme that does not accept this user',
'              then case when l_lang = ''ar'' then apex_escape.html(''غير مسموح.'') else ''Not allowed.'' end',
'              when l_lang = ''ar''',
'              then apex_escape.html(''حدّد في المنطقة «مخطط الصلاحية للتغييرات»: بلا حسابات حاضر هو من يقرر من يدير خدمات الذكاء الاصطناعي.'')',
'              else ''Set the region''''s Authorization scheme for changes: without Hader''''s accounts it decides who manages the AI services.'' end',
'      || ''</p></div>'');',
'    return null;',
'  end if;',
'  sys.htp.p(''<div id="'' || apex_escape.html_attribute(l_id) || ''" class="hais"></div>'');',
'  apex_javascript.add_onload_code(',
'    ''hdrAIServices.init('' ||',
'    apex_javascript.add_value(l_id) ||',
'    apex_javascript.add_value(apex_plugin.get_ajax_identifier) ||',
'    apex_javascript.add_value(case when can_change(p_region) then ''Y'' else ''N'' end) ||',
'    apex_javascript.add_value(nvl(p_region.attribute_04, ''AUTO''), false) || '');'');',
'  return null;',
'end render;',
'',
'function ajax (',
'  p_region in apex_plugin.t_region,',
'  p_plugin in apex_plugin.t_plugin )',
'  return apex_plugin.t_region_ajax_result',
'is',
'  l_what varchar2(20) := apex_application.g_x01;',
'  l_ai   varchar2(200) := hdr_ai_obj(p_region.attribute_01, ''HDR_AI'');',
'  l_clob clob;',
'  l_id   number;',
'  function f (p_list in apex_application_global.vc_arr2) return varchar2 is',
'  begin',
'    return case when p_list.count > 0 then p_list(1) end;',
'  end f;',
'begin',
'  if not can_see(p_region) then',
'    raise_application_error(-20699, ''not allowed (set an authorization scheme for changes on the region)'');',
'  end if;',
'  if l_what = ''LIST'' then',
'    execute immediate ''begin :r := '' || l_ai || ''.services(:u); end;'' using out l_clob, in v(''APP_USER'');',
'    hdr_ai_print(l_clob);',
'  elsif l_what = ''SERVICE'' then          -- a test: the service chosen, a disabled one too (its key only for the browser)',
'    execute immediate ''begin :r := '' || l_ai || ''.service(:u, :s, ''''Y''''); end;''',
'      using out l_clob, in v(''APP_USER''), in apex_application.g_x02;',
'    hdr_ai_print(l_clob);',
'  elsif l_what = ''RELAY'' then            -- a test of a service called from the database',
'    execute immediate ''begin :r := '' || l_ai || ''.relay(:u, :s, :b, ''''Y''''); end;''',
'      using out l_clob, in v(''APP_USER''), in apex_application.g_x02, in apex_application.g_clob_01;',
'    hdr_ai_print(l_clob);',
'  elsif l_what in (''SAVE'', ''DROP'', ''TESTED'') then',
'    if not can_change(p_region) then',
'      raise_application_error(-20699, ''not allowed (set an authorization scheme for changes on the region)'');',
'    end if;',
'    if l_what = ''SAVE'' then',
'      -- x02 id, x03 static id, x04 name, x05 provider, x06 address, x07 model, x08 called from, x09 credential,',
'      -- x10 max tokens; f01 the key (empty: kept; ''-'': none), f02 default, f03 enabled, f04 requests per user per',
'      -- minute, f05 Y: the credential chosen again (for a new address)',
'      execute immediate ''begin :r := '' || l_ai || ''.save_service(:u, :i, :st, :nm, :pr, :ur, :md, :cl, :cr, :ky, :tk, :df, :en, :pm, :ca); end;''',
'        using out l_id, in v(''APP_USER''), in to_number(apex_application.g_x02), in apex_application.g_x03,',
'              in apex_application.g_x04, in apex_application.g_x05, in apex_application.g_x06, in apex_application.g_x07,',
'              in apex_application.g_x08, in apex_application.g_x09, in f(apex_application.g_f01),',
'              in to_number(apex_application.g_x10), in f(apex_application.g_f02), in f(apex_application.g_f03),',
'              in to_number(f(apex_application.g_f04)), in f(apex_application.g_f05);',
'    elsif l_what = ''DROP'' then',
'      execute immediate ''begin '' || l_ai || ''.drop_service(:u, :i); end;'' using in v(''APP_USER''), in to_number(apex_application.g_x02);',
'    else',
'      execute immediate ''begin '' || l_ai || ''.tested(:u, :i, :r); end;''',
'        using in v(''APP_USER''), in to_number(apex_application.g_x02), in substr(apex_application.g_x03, 1, 400);',
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(''ok'', true);',
'    apex_json.write(''id'', l_id);',
'    apex_json.close_object;',
'  end if;',
'  return null;',
'exception when others then',
'  hdr_ai_failed(sqlerrm);',
'  return null;',
'end ajax;'))
,p_api_version=>1
,p_render_function=>'render'
,p_ajax_function=>'ajax'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Hader AI: the AI services of this schema, as APEX 24 and later has them in Workspace Utilities > Generative AI, for APEX 19.2 and later: Google Gemini, OpenAI, Anthropic or any OpenAI-compatible server (Ollama, Groq, Mistral, DeepSeek...), the model, the key (written, never shown again) or a Web Credential (its Static ID starting with AI_, its Valid for URLs the provider''s address), and where the calls are made from: the user''s browser (nothing to set up in the database, Oracle 11g included; the key reaches the browsers of the users allowed to use it: restrict it at the provider) or the database (the key never leaves it; the database must reach the provider over HTTPS; each request is rebuilt there: the service''s model, its tokens at most, function tools only, so many requests a user a minute). Test Connection asks the service once.'
,p_version_identifier=>'1.3'
,p_files_version=>72943
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91735000000002)
,p_plugin_id=>wwv_flow_api.id(91735000000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Owner of Hader AI'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_display_length=>30
,p_max_length=>30
,p_is_translatable=>false
,p_help_text=>'Schema of Hader AI (the one with HDR_AI). Empty = the application''s parsing schema. Another schema: GRANT EXECUTE ON HDR_AI TO <this application''s schema>.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91735000000003)
,p_plugin_id=>wwv_flow_api.id(91735000000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Allow changes'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>'Off = look and test only.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91735000000004)
,p_plugin_id=>wwv_flow_api.id(91735000000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Authorization scheme for changes'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_display_length=>30
,p_max_length=>255
,p_is_translatable=>false
,p_help_text=>'Optional: name of an authorization scheme of the application (e.g. Administration Rights). Only users it accepts may change things; the others see the region read only. Checked on the server for every request. Required when Hader''s accounts are not used (Hader AI alone): then only the users it accepts see, test and change the services.'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(91735000000005)
,p_plugin_id=>wwv_flow_api.id(91735000000001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Language'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'AUTO'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Automatic follows the application language.'
);
wwv_flow_api.create_plugin_attr_value(
 p_id=>wwv_flow_api.id(91735000000006)
,p_plugin_attribute_id=>wwv_flow_api.id(91735000000005)
,p_display_sequence=>10
,p_display_value=>'Automatic'
,p_return_value=>'AUTO'
);
wwv_flow_api.create_plugin_attr_value(
 p_id=>wwv_flow_api.id(91735000000007)
,p_plugin_attribute_id=>wwv_flow_api.id(91735000000005)
,p_display_sequence=>20
,p_display_value=>'العربية'
,p_return_value=>'AR'
);
wwv_flow_api.create_plugin_attr_value(
 p_id=>wwv_flow_api.id(91735000000008)
,p_plugin_attribute_id=>wwv_flow_api.id(91735000000005)
,p_display_sequence=>30
,p_display_value=>'English'
,p_return_value=>'EN'
);
end;
/
